const CAT_HEADLINES=['WOW! Noch dein ganzes Mana?!','Ich trau meinen Augen nicht!','Ein magischer Null-Verbrauch?!','Sag bloß, du hast Mana gespart!','Kein einziger Mana-Kristall weg?!','Na sowas! Alles noch da?'];
